// grow to len 3, print Count and Capacity

exercises.solution:
using System.Collections.Generic;

var s = new List<int>(10);
s.Add(0); s.Add(0); s.Add(0);
Console.WriteLine($"{s.Count} {s.Capacity}");

var n = new[] { 1, 2, 3, 4, 5 };
var sliced = n.Skip(1).Take(3).ToArray();
Console.WriteLine($"[{string.Join(" ", sliced)}]");

